import './CardVeiculo.css';

function CardVeiculo(props){
    return(
        <div className="col"> 
            <div className="card shadow-sm"> 
                <img
                    src={props.img}
                    className= "bd-placeholder-img card-img-top" 
                    alt={props.titulo}
                    width="100%" 
                    height="300"
                />    
                <div className="d-flex justify-content-between align-items-center">                       
                         {/* Seu título personalizado */}
                         <p className="nome-veiculo">{props.titulo}</p> 

                         {/* Adicionei 'm-0' (margin 0) para o preço não empurrar o layout */}
                         <p className="m-0 text-muted"><b>R$ {props.preco}</b></p>
                    </div>
                 </div> 
            </div>

    );
}

export default CardVeiculo;
